def canon(name):
    def capitalize_part(part):
        if len(part) >= 2 and part[0].lower() == 'm' and part[1].lower() == 'c':
            return 'Mc' + part[2:].capitalize()
        return part.capitalize()

    parts = name.split()
    processed = []
    for part in parts:
        initials = part.split('.')
        cap_initials = [capitalize_part(i) for i in initials if i]
        processed_part = '.'.join(cap_initials)
        processed.append(processed_part)
    return ' '.join(processed)
